/**
 * SystemDevice: the simulated Kode Dot as the page sees it, over the firmware team's system layer
 * (runtime/web-adapter, `DotbenchSystem`): kodeOS plus the apps installed in it, on one persistent device.
 * The Dot always boots kodeOS; apps are installed into it and opened from its own list (or from the page's app
 * manager, which asks the system for the same thing). Restarts between programs never reach the page: it keeps this
 * one object, reads frames and outputs from it and is told which program runs.
 *
 * The system layer is imported lazily (copied into src/generated by scripts/sync-adapter.mjs), so the page and the
 * mock never load it. Tests pass `createSystem` with a fake.
 *
 * What does not fit KodeDevice 1:1 is exposed through `RealDevice`: the running program, the installed apps and what
 * can be done with them, crash reason, runtime-support problems, worker/memory numbers, device export/import.
 */
import type { AdapterLogLine, AdapterOutputs, AdapterStatusDetail, AdapterSystem, InstalledApp, Program } from './adapter-types';
import { Atom, LogBuffer } from './observable';
import {
  SCREEN_HEIGHT,
  SCREEN_WIDTH,
  type ButtonId,
  type DeviceInfo,
  type DeviceStatus,
  type Frame,
  type HardwareAreas,
  type KodeDevice,
  type LoadOptions,
  type LogStream,
  type Observable,
  type Rgb,
} from './types';

export class NotWiredError extends Error {
  constructor() {
    super('WebAssembly adapter not wired yet.');
    this.name = 'NotWiredError';
  }
}

// ------------------------------------------------------------------ support

export type RuntimeProblemCode = 'no-webassembly' | 'not-isolated' | 'no-shared-array-buffer' | 'no-wasm-threads' | 'no-decompression-stream';

export interface RuntimeEnv {
  crossOriginIsolated?: boolean;
  SharedArrayBuffer?: unknown;
  WebAssembly?: { Memory: new (d: { initial: number; maximum: number; shared: boolean }) => unknown };
  DecompressionStream?: unknown;
}

/** What the browser lacks to run a .dotbench (empty = fine). Pure, so it is unit-tested. */
export function checkRuntime(env: RuntimeEnv = globalThis as unknown as RuntimeEnv): RuntimeProblemCode[] {
  const out: RuntimeProblemCode[] = [];
  if (typeof env.WebAssembly === 'undefined') return ['no-webassembly'];
  if (!env.crossOriginIsolated) out.push('not-isolated');
  if (typeof env.SharedArrayBuffer === 'undefined') out.push('no-shared-array-buffer');
  else {
    try {
      new env.WebAssembly.Memory({ initial: 1, maximum: 1, shared: true });
    } catch {
      out.push('no-wasm-threads');
    }
  }
  if (typeof env.DecompressionStream === 'undefined') out.push('no-decompression-stream');
  return out;
}

export class UnsupportedRuntimeError extends Error {
  constructor(readonly problems: RuntimeProblemCode[]) {
    super(`This browser cannot run apps: ${problems.join(', ')}`);
    this.name = 'UnsupportedRuntimeError';
  }
}

// ------------------------------------------------------------------- device

export interface StatusDetail {
  status: DeviceStatus;
  /** crash cause, or why the Dot is starting again (an app crashed, for example) */
  reason?: string;
  /** true while the Dot restarts by itself (after an app crashed) */
  restarting?: boolean;
}

export type { InstalledApp, Program };

/** What the page can additionally do with the real device (the mock has none of this). */
export interface RealDevice extends KodeDevice {
  readonly detail: Observable<StatusDetail>;
  /** Empty when this browser can run the Dot. Checked once at construction. */
  readonly unsupported: readonly RuntimeProblemCode[];
  /** What runs right now: kodeOS (kind 'os') or one of its apps. Null while nothing runs. */
  readonly program: Observable<Program | null>;
  /** The apps installed in kodeOS, in install order. */
  readonly apps: Observable<readonly InstalledApp[]>;
  /** Install a .dotbench into kodeOS (it restarts once to list it). Resolves with the app's id. */
  install(bundle: ArrayBuffer | Uint8Array): Promise<string>;
  /** Open an installed app, as a tap on it in kodeOS does. */
  launch(id: string): Promise<void>;
  /** Remove an installed app, as kodeOS's own Remove does. */
  removeApp(id: string): Promise<void>;
  /** Leave the running app for kodeOS (the same as holding the bottom button for 3 s). */
  home(): Promise<void>;
  /** Erase the whole Dot (settings, files, apps): the next start is a first boot with the factory apps. */
  factoryReset(): Promise<void>;
  stats(): { workers: number; memoryBytes: number };
  /**
   * Events of the hardware areas (`area:<name>:<type>`) and the log-level ones the system layer re-emits. The subscription
   * outlives programs: it is the same device underneath, whichever program runs, and may be made before the system is open.
   */
  onEvent(name: string, cb: (data: unknown) => void): () => void;
  releaseAll(): void;
  exportDevice(): Promise<{ data: Uint8Array; extension: string }>;
  importDevice(data: Uint8Array): Promise<void>;
}
export const isRealDevice = (d: KodeDevice): d is RealDevice => d.info.kind === 'wasm' && 'detail' in d;

export interface SystemDeviceOptions {
  createSystem?: () => Promise<AdapterSystem>;
  env?: RuntimeEnv;
}

/** Where the Dot's software is served from (written by scripts/prepare-apps.mjs). */
export const APPS_URL = '/apps/';
export const OS_PACKAGE = 'kodeos.dotbench';
/** The Dot's own database in this browser (settings, files, installed apps). Not shared with anything else. */
export const SYSTEM_STORE = 'kodedot-system';

/** After the screen or a button is released, what the firmware stored is saved this long afterwards (twice: once quickly, once after slower writes). */
export const SAVE_AFTER_INPUT_MS = [150, 700] as const;
/** While the Dot runs, what changed is saved at least this often. */
export const SAVE_EVERY_MS = 1000;

/** factory.json: `{"format":1,"apps":["a.dotbench", ...]}`. Anything else counts as "no factory apps". */
export function parseFactory(json: unknown): string[] {
  const j = json as { format?: unknown; apps?: unknown } | null;
  if (!j || j.format !== 1 || !Array.isArray(j.apps)) return [];
  return j.apps.filter((a): a is string => typeof a === 'string' && /^[\w.-]+\.dotbench$/.test(a));
}

async function fetchBytes(name: string): Promise<Uint8Array> {
  const r = await fetch(APPS_URL + name);
  if (!r.ok) throw new Error(`HTTP ${r.status} for ${name}`);
  return new Uint8Array(await r.arrayBuffer());
}

const defaultSystem = async (): Promise<AdapterSystem> => {
  const [{ DotbenchSystem }, { IdbBackend }, os, factory] = await Promise.all([
    import('../generated/web-adapter/dotbench-system.js'),
    import('../generated/web-adapter/persist-idb.js'),
    fetchBytes(OS_PACKAGE),
    fetch(APPS_URL + 'factory.json')
      .then((r) => (r.ok ? r.json() : null))
      .then(parseFactory, () => []),
  ]);
  return new DotbenchSystem({ os, persist: new IdbBackend({ name: SYSTEM_STORE }), factory: { apps: factory, fetch: fetchBytes } });
};

export class SystemDevice implements RealDevice {
  readonly info: DeviceInfo = { kind: 'wasm', label: 'WebAssembly', runsBundles: true };
  readonly unsupported: readonly RuntimeProblemCode[];

  private _status = new Atom<DeviceStatus>('idle');
  private _detail = new Atom<StatusDetail>({ status: 'idle' });
  private _appName = new Atom<string | null>(null);
  private _program = new Atom<Program | null>(null);
  private _apps = new Atom<readonly InstalledApp[]>([]);
  private _backlight = new Atom(100);
  private _panelOn = new Atom(true);
  private _led = new Atom<Rgb>({ r: 0, g: 0, b: 0 });
  private _haptic = new Atom(0);
  private _log = new LogBuffer();

  readonly status: Observable<DeviceStatus> = this._status;
  readonly detail: Observable<StatusDetail> = this._detail;
  readonly appName: Observable<string | null> = this._appName;
  readonly program: Observable<Program | null> = this._program;
  readonly apps: Observable<readonly InstalledApp[]> = this._apps;
  readonly backlight: Observable<number> = this._backlight;
  readonly panelOn: Observable<boolean> = this._panelOn;
  readonly led: Observable<Rgb> = this._led;
  readonly haptic: Observable<number> = this._haptic;
  readonly log: LogStream = this._log;
  readonly areas: Readonly<Partial<HardwareAreas>>;

  private sys: AdapterSystem | null = null;
  private sysPromise: Promise<AdapterSystem> | null = null;
  private offs: (() => void)[] = [];
  private evSubs = new Set<{ name: string; cb: (d: unknown) => void; off?: () => void }>();
  private disposed = false;
  /** true once the Dot was powered on and not stopped since */
  private on = false;
  private data = new Uint8ClampedArray(new ArrayBuffer(SCREEN_WIDTH * SCREEN_HEIGHT * 4));
  private blank: Frame;
  private frame: Frame;
  private sysSeq = -1;
  private outSeq = 0;
  private saveTimers: ReturnType<typeof setTimeout>[] = [];
  private saveTicker: ReturnType<typeof setInterval> | null = null;

  constructor(private opts: SystemDeviceOptions = {}) {
    this.unsupported = checkRuntime(opts.env);
    const black = new Uint8ClampedArray(new ArrayBuffer(SCREEN_WIDTH * SCREEN_HEIGHT * 4));
    for (let i = 3; i < black.length; i += 4) black[i] = 255;
    this.blank = { seq: 0, width: SCREEN_WIDTH, height: SCREEN_HEIGHT, data: black };
    this.frame = this.blank;
    // areas: whatever JS glue the running program registered, looked up live (null/absent when none)
    this.areas = new Proxy({} as Partial<HardwareAreas>, {
      get: (_t, key) => (typeof key === 'string' ? (this.sys?.area(key) ?? undefined) : undefined),
      has: (_t, key) => typeof key === 'string' && !!this.sys?.area(key),
    });
  }

  private ensureSystem(): Promise<AdapterSystem> {
    if (this.disposed) return Promise.reject(new Error('device disposed'));
    if (this.unsupported.length) return Promise.reject(new UnsupportedRuntimeError([...this.unsupported]));
    this.sysPromise ??= (this.opts.createSystem ?? defaultSystem)().then(
      (s) => {
        if (this.disposed) {
          s.dispose();
          throw new Error('device disposed');
        }
        this.sys = s;
        for (const sub of this.evSubs) sub.off ??= s.on(sub.name, sub.cb as never);
        this.offs.push(
          s.on('status', (d: AdapterStatusDetail) => this.onStatus(d)),
          s.on('program', (p: Program) => this.onProgram(p)),
          s.on('apps', () => this.refreshApps()),
          s.on('log', (l: AdapterLogLine) => this._log.push(l.level, l.text, l.ts)),
          s.on('outputs', (o: AdapterOutputs) => this.applyOutputs(o)),
        );
        return s;
      },
      (e) => {
        this.sysPromise = null; // a failed download can be tried again
        throw e;
      },
    );
    return this.sysPromise;
  }

  /** The system object itself, for what attaches to it directly (the parts engine). */
  system(): Promise<AdapterSystem> {
    return this.ensureSystem();
  }

  onEvent(name: string, cb: (data: unknown) => void): () => void {
    const sub: { name: string; cb: (d: unknown) => void; off?: () => void } = { name, cb };
    this.evSubs.add(sub);
    if (this.sys) sub.off = this.sys.on(name, cb as never);
    return () => {
      sub.off?.();
      this.evSubs.delete(sub);
    };
  }

  private onStatus(s: AdapterStatusDetail): void {
    if (s.status === 'restart-requested') return; // the system layer plays the bootloader; nothing to show
    if (s.status === 'booting') this._detail.set(s.reason ? { status: 'booting', reason: s.reason, restarting: true } : { status: 'booting' });
    else this._detail.set(s.status === 'crashed' ? { status: 'crashed', reason: s.reason } : { status: s.status });
    this._status.set(s.status);
    if (s.status === 'running' && this.sys) this.applyOutputs(this.sys.outputs());
    if (s.status === 'idle' || s.status === 'crashed') {
      this._led.set({ r: 0, g: 0, b: 0 });
      this._haptic.set(0);
    }
    if (s.status === 'idle') {
      this.sysSeq = -1;
      this.frame = { ...this.blank, seq: ++this.outSeq };
      this._program.set(null);
      this._appName.set(null);
    }
  }

  private onProgram(p: Program): void {
    this._program.set({ id: p.id, name: p.name, kind: p.kind });
    this._appName.set(p.name);
    this.refreshApps();
  }

  private refreshApps(): void {
    const s = this.sys;
    if (!s) return;
    let list: InstalledApp[];
    try {
      list = s.list().map((a) => ({ id: a.id, project: a.project, name: a.name, version: a.version, category: a.category, size: a.size, hasBundle: a.hasBundle }));
    } catch {
      return; // the device is not open yet
    }
    if (JSON.stringify(list) !== JSON.stringify(this._apps.get())) this._apps.set(list);
  }

  private applyOutputs(o: AdapterOutputs): void {
    const cur = this._led.get();
    if (cur.r !== o.led.r || cur.g !== o.led.g || cur.b !== o.led.b) this._led.set({ r: o.led.r, g: o.led.g, b: o.led.b });
    this._haptic.set(o.haptic);
    this._backlight.set(o.backlight);
    this._panelOn.set(o.panelOn);
  }

  // saving ------------------------------------------------------------------
  // What the firmware stores (kodeOS's settings, files, the clock) lives in persistent regions that the system layer
  // mirrors to IndexedDB. Its own timing waits for the firmware to stop writing for 0.8 s, and kodeOS never stops
  // (it marks a region dirty well over a thousand times a second while idle), so by itself the mirror is only
  // brought up to date every 5 s, or when the page is hidden or closed. A setting changed and then lost to a crashed
  // or killed tab a second later would be the result. So the page asks for the cheap "save what changed" itself:
  // shortly after every release of the screen or a button (that is when settings change), and once a second while
  // the Dot runs. Nothing is written when nothing changed.
  private save = (): void => {
    if (!this.on || !this.sys) return;
    void this.sys.flushPersist().catch(() => {
      /* the system reports storage errors itself */
    });
  };
  private saveSoon(): void {
    for (const t of this.saveTimers) clearTimeout(t);
    this.saveTimers = SAVE_AFTER_INPUT_MS.map((ms) => setTimeout(this.save, ms));
  }
  private saving(on: boolean): void {
    if (this.saveTicker) clearInterval(this.saveTicker);
    this.saveTicker = on ? setInterval(this.save, SAVE_EVERY_MS) : null;
    if (!on) {
      for (const t of this.saveTimers) clearTimeout(t);
      this.saveTimers = [];
    }
  }

  // lifecycle ---------------------------------------------------------------
  /** KodeDevice's "hand over a bundle": for the Dot that is installing it. `start()` powers the Dot on. */
  async load(bundle: ArrayBuffer, _options: LoadOptions): Promise<void> {
    await this.install(bundle);
  }
  /** Power on: kodeOS boots (the first boot of an empty Dot installs the factory apps first). */
  async start(): Promise<void> {
    const s = await this.ensureSystem();
    this.on = true;
    this.saving(true);
    this._status.set('booting');
    this._detail.set({ status: 'booting' });
    try {
      await s.start();
    } catch (e) {
      this.fail(e);
      throw e;
    }
    this.refreshApps();
  }
  /** Reset the Dot (a power-on reset: kodeOS comes up); powers it on when it is off. */
  async restart(): Promise<void> {
    if (!this.on || !this.sys) return this.start();
    try {
      await this.sys.powerOnReset();
    } catch (e) {
      this.fail(e);
      throw e;
    }
  }
  stop(): void {
    this.on = false;
    this.saving(false);
    this.sys?.stop(); // the system saves everything as it stops the program
  }
  dispose(): void {
    this.disposed = true;
    this.on = false;
    this.saving(false);
    for (const o of this.offs) o();
    this.offs = [];
    for (const sub of this.evSubs) sub.off?.();
    this.evSubs.clear();
    this.sys?.dispose();
    this.sys = null;
  }
  /** A start that could not happen at all (download failed, storage refused): shown like a crash, with the reason. */
  private fail(e: unknown): void {
    if (this._status.get() === 'crashed') return;
    const reason = String((e as Error)?.message ?? e);
    this._detail.set({ status: 'crashed', reason });
    this._status.set('crashed');
  }

  // apps --------------------------------------------------------------------
  async install(bundle: ArrayBuffer | Uint8Array): Promise<string> {
    const s = await this.ensureSystem();
    const { id } = await s.install(bundle instanceof Uint8Array ? bundle : new Uint8Array(bundle));
    this.refreshApps();
    return id;
  }
  async launch(id: string): Promise<void> {
    const s = await this.ensureSystem();
    if (!this.on) await this.start();
    await s.launch(id);
  }
  async removeApp(id: string): Promise<void> {
    const s = await this.ensureSystem();
    await s.remove(id);
    this.refreshApps();
  }
  async home(): Promise<void> {
    await this.sys?.home();
  }
  async factoryReset(): Promise<void> {
    const s = await this.ensureSystem();
    await s.factoryReset();
    this.refreshApps();
  }

  // screen ------------------------------------------------------------------
  getFrame(): Frame {
    const s = this.sys;
    if (!s || this._status.get() === 'idle') return this.frame;
    const seq = s.copyFrame(this.data, this.sysSeq);
    if (seq !== this.sysSeq) {
      this.sysSeq = seq;
      this.frame = { seq: ++this.outSeq, width: SCREEN_WIDTH, height: SCREEN_HEIGHT, data: this.data };
    }
    return this.frame;
  }

  // inputs ------------------------------------------------------------------
  setButton(id: ButtonId, pressed: boolean): void {
    this.sys?.button(id, pressed);
    if (!pressed) this.saveSoon();
  }
  setTouch(x: number, y: number, down: boolean): void {
    this.sys?.touch(x, y, down);
    if (!down) this.saveSoon();
  }
  releaseAll(): void {
    this.sys?.releaseAll();
  }

  // console / time ------------------------------------------------------------
  sendConsole(line: string): void {
    // the system echoes it as an 'input' line through the log event
    if (this.sys) this.sys.sendConsole(line);
    else this._log.push('input', line);
  }
  time(): number {
    return this.sys?.time() ?? Date.now();
  }

  stats(): { workers: number; memoryBytes: number } {
    return { workers: this.sys?.workerCount ?? 0, memoryBytes: this.sys?.wasmMemoryBytes ?? 0 };
  }

  // device persistence --------------------------------------------------------
  /** The whole Dot as one file: settings, files, the installed apps and their packages. */
  async exportDevice(): Promise<{ data: Uint8Array; extension: string }> {
    const s = await this.ensureSystem();
    return { data: s.exportDeviceFile(), extension: 'dotbench-device' };
  }
  /** Replace the whole Dot with such a file: it is stopped, replaced and powered on again. */
  async importDevice(data: Uint8Array): Promise<void> {
    const s = await this.ensureSystem();
    s.stop();
    await s.device.importDeviceFile(data);
    await this.start();
  }
}
